const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export class TheatreGame {
 constructor(onEvent=()=>{}){this.onEvent=onEvent;this.mode='rehearsal';this.difficulty='normal';this.reset();}
 emit(type,data={}){this.onEvent(type,data);}
 reset(){this.actors=CAST.map(a=>({...a,tx:a.x,tz:a.z,moving:false,run:false,stamina:100}));this.act=0;this.elapsed=0;this.running=false;this.started=false;this.finished=false;this.intermission=false;this.speed=1;this.audience=86;this.score=0;this.combo=0;this.bestCombo=0;this.rescues=3;this.success=0;this.missed=0;this.resolved=0;this.incidentCount=0;this.incident=null;this.incidentCursor=0;this.incidentOrder=[0,1,2,3,4,5,6,7].sort(()=>Math.random()-.5);this.slow=0;this.hold=0;this.light='moon';this.intensity=.75;this.audio=null;this.audioAt=-100;this.cues=ACTS[0].cues.map(c=>({...c,status:'pending'}));this.actResults=[];this.eventsThisAct=0;this.emit('reset');}
 setMode(mode){if(this.mode===mode)return;this.mode=mode;this.reset();this.emit('mode');}
 toggle(){if(this.finished){this.reset();}if(this.intermission){this.nextAct();return;}this.started=true;this.running=!this.running;this.emit('transport');}
 move(index,x,z){if(this.finished||this.intermission)return;const a=this.actors[index];a.tx=clamp(x,-5.9,5.9);a.tz=clamp(z,-2.8,3.1);a.moving=true;this.emit('move',{index});}
 mark(index){const mark=ACTS[this.act].marks.find(m=>m.actor===index);if(mark)this.move(index,mark.x,mark.z);}
 lightAction(value){this.light=value;this.checkCues();}
 soundAction(value){this.audio=value;this.audioAt=this.elapsed;this.checkCues();}
 cueAction(index){const c=this.cues[index];if(!c||c.status!=='pending')return;if(c.type==='move'){this.move(c.actor,c.x,c.z);this.emit('select',{index:c.actor});}else if(c.type==='ensemble'){ACTS[this.act].marks.forEach(m=>this.move(m.actor,m.x,m.z));}else this.emit('cueAction',{cue:c});}
 checkCues(){if(!this.running)return;for(const c of this.cues){if(c.status!=='pending')continue;const open=c.at-5;const close=c.at+(this.difficulty==='hard'?10:15);if(this.elapsed<open)continue;let done=false;if(c.type==='move'){const a=this.actors[c.actor];done=Math.hypot(a.x-c.x,a.z-c.z)<.55;}if(c.type==='ensemble')done=ACTS[this.act].marks.every(m=>Math.hypot(this.actors[m.actor].x-m.x,this.actors[m.actor].z-m.z)<.55);if(c.type==='lighting')done=this.light===c.value&&this.intensity>=.6;if(c.type==='audio')done=this.audio===c.value&&this.audioAt>=open&&this.elapsed-this.audioAt<8;
   if(done){c.status='done';this.success++;this.combo++;this.bestCombo=Math.max(this.bestCombo,this.combo);const points=Math.round((c.type==='move'||c.type==='ensemble'?100:80)*(1+Math.min(this.combo-1,5)*.1));this.score+=points;this.audience=clamp(this.audience+3,0,100);this.emit('cueComplete',{cue:c,points});}else if(this.mode==='performance'&&this.elapsed>close){c.status='missed';this.missed++;this.combo=0;this.audience=clamp(this.audience-7,0,100);this.emit('cueMissed',{cue:c});}}
 }
 triggerIncident(){if(this.incident||!this.running||this.intermission)return;const event=INCIDENTS[this.incidentOrder[this.incidentCursor++%8]];const duration=this.difficulty==='hard'?12:this.difficulty==='easy'?24:18;this.incident={...event,left:duration,duration};this.incidentCount++;this.eventsThisAct++;this.emit('incident',{incident:this.incident});}
 resolveIncident(optionIndex,rescue=false){if(!this.incident)return false;if(rescue&&this.rescues<=0)return false;const event=this.incident;let option=rescue?{points:75,change:4}:event.options[optionIndex];if(!option)return false;if(rescue)this.rescues--;const succeeded=!option.risk||Math.random()<option.risk;if(succeeded){this.resolved++;this.score+=option.points;this.audience=clamp(this.audience+option.change,0,100);this.slow=option.slow||0;this.hold=option.hold||0;if(option.stamina)this.actors.forEach(a=>a.stamina=clamp(a.stamina+option.stamina,0,100));if(option.mood){this.light=option.mood;this.emit('light',{value:option.mood});}if(option.set)this.emit('set');}else{this.audience=clamp(this.audience-7,0,100);this.combo=0;}this.incident=null;this.emit('incidentResolved',{succeeded,option,event,rescue});return true;}
 update(delta){const movingAllowed=(!this.started||this.running)&&!this.intermission&&!this.finished;const dt=delta*this.speed;if(movingAllowed){this.slow=Math.max(0,this.slow-dt);this.hold=Math.max(0,this.hold-dt);this.actors.forEach(a=>{const distance=Math.hypot(a.tx-a.x,a.tz-a.z);a.moving=distance>.045;if(a.moving&&this.hold<=0){let speed=(a.run&&a.stamina>8?2.9:1.3)*(this.slow>0?.55:1);let amount=Math.min(distance,dt*speed);a.x+=(a.tx-a.x)/distance*amount;a.z+=(a.tz-a.z)/distance*amount;a.stamina=clamp(a.stamina-dt*(a.run?4:.35),0,100);}else if(!a.moving)a.stamina=clamp(a.stamina+dt*2,0,100);});}if(!this.running||this.intermission||this.finished)return;this.elapsed+=dt;this.checkCues();if(this.incident){this.incident.left-=dt;if(this.incident.left<=0){const event=this.incident;this.incident=null;this.audience=clamp(this.audience-(this.mode==='performance'?10:0),0,100);this.combo=0;this.emit('incidentTimeout',{event});}}else if((this.eventsThisAct===0&&this.elapsed>23)||(this.eventsThisAct===1&&this.elapsed>51))this.triggerIncident();if(this.elapsed>=ACTS[this.act].duration)this.endAct();}
 endAct(){if(this.intermission||this.finished)return;this.elapsed=ACTS[this.act].duration;this.running=false;if(this.incident){const event=this.incident;this.incident=null;this.audience=clamp(this.audience-(this.mode==='performance'?10:0),0,100);this.combo=0;this.emit('incidentTimeout',{event});}this.cues.forEach(c=>{if(c.status==='pending'){c.status='missed';this.missed++;}});this.actResults.push({act:this.act,success:this.cues.filter(c=>c.status==='done').length,score:this.score});if(this.act===2){this.finished=true;this.emit('finish',{result:this.result()});}else{this.intermission=true;this.emit('actEnd');}}
 nextAct(){if(!this.intermission)return;this.act++;this.elapsed=0;this.intermission=false;this.started=true;this.running=true;this.eventsThisAct=0;this.incident=null;this.audio=null;this.audioAt=-100;this.cues=ACTS[this.act].cues.map(c=>({...c,status:'pending'}));this.actors.forEach(a=>{a.tx=a.x;a.tz=a.z;a.stamina=clamp(a.stamina+25,0,100);});this.emit('actStart');}
 result(){const accuracy=Math.round(this.success/15*100),score=Math.round(this.score+this.audience*5),grade=accuracy>=87&&this.audience>=80?'S':accuracy>=67&&this.audience>=60?'A':accuracy>=40?'B':'C';return {score,grade,accuracy,audience:Math.round(this.audience),bestCombo:this.bestCombo,resolved:this.resolved,incidentCount:this.incidentCount,mode:this.mode,date:new Date().toISOString(),title:grade==='S'?'全场起立，掌声不息':grade==='A'?'一场精彩的演出':grade==='B'?'好戏仍有进步空间':'每位导演都有第一次'};}
}
